function event_timer(e)
	x_npc = e.self:GetX();
	y_npc = e.self:GetY();
	if (x_npc >= (x_dest - 100) and x_npc <= (x_dest + 100) and y_npc >= (y_dest - 100) and y_npc <= (y_dest + 100)) then
		rescue = 2;
		eq.stop_timer("docks");
	end
end

