		e.self:CastSpell(5680, e.self:GetTarget():GetID()); -- Spell: Gaze of Anguish
		eq.set_timer("gaze", 70 * 1000);
	elseif e.timer == "mark" then
		local now_clients = eq.get_entity_list():GetClientList();
